<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\View;use App\Services\PermissionService;
final class AdminController {
 private function guard(string $p):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$p);}
 public function units():void{$this->guard('admin.units.view');$units=Database::connection()->query('SELECT * FROM units ORDER BY name')->fetchAll();View::render('admin/units',compact('units'));}
 public function storeUnit():void{$this->guard('admin.units.create');Security::verifyCsrf();$name=trim((string)($_POST['name']??''));$code=trim((string)($_POST['code']??''));if($name==='')exit('نام واحد الزامی است.');$s=Database::connection()->prepare('INSERT INTO units(name,code,is_active,created_at,updated_at) VALUES(:name,:code,1,GETDATE(),GETDATE())');$s->execute(['name'=>$name,'code'=>$code?:null]);Security::redirect('/admin/units');}
 public function groups():void{$this->guard('admin.groups.view');$pdo=Database::connection();$groups=$pdo->query('SELECT * FROM groups ORDER BY name')->fetchAll();$permissions=$pdo->query('SELECT * FROM permissions ORDER BY code')->fetchAll();foreach($groups as &$g){$s=$pdo->prepare('SELECT permission_code FROM group_permissions WHERE group_id=:id');$s->execute(['id'=>$g['id']]);$g['permissions']=array_column($s->fetchAll(),'permission_code');}View::render('admin/groups',compact('groups','permissions'));}
 public function storeGroup():void{$this->guard('admin.groups.create');Security::verifyCsrf();$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));if($name==='')exit('نام گروه الزامی است.');$s=Database::connection()->prepare('INSERT INTO groups(name,description,created_at,updated_at) VALUES(:name,:description,GETDATE(),GETDATE())');$s->execute(['name'=>$name,'description'=>$description?:null]);Security::redirect('/admin/groups');}
 public function groupPermissions(int $id):void{$this->guard('admin.groups.permissions');Security::verifyCsrf();$pdo=Database::connection();$selected=(array)($_POST['permissions']??[]);$pdo->beginTransaction();try{$s=$pdo->prepare('DELETE FROM group_permissions WHERE group_id=:id');$s->execute(['id'=>$id]);$s=$pdo->prepare('INSERT INTO group_permissions(group_id,permission_code,created_at,updated_at) VALUES(:id,:code,GETDATE(),GETDATE())');foreach($selected as $code)$s->execute(['id'=>$id,'code'=>(string)$code]);$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}Security::redirect('/admin/groups');}
 public function users():void{$this->guard('admin.users.view');$pdo=Database::connection();$users=$pdo->query('SELECT id,username,name,is_active FROM users ORDER BY username')->fetchAll();$groups=$pdo->query('SELECT id,name FROM groups ORDER BY name')->fetchAll();$permissions=$pdo->query('SELECT code,name FROM permissions ORDER BY code')->fetchAll();foreach($users as &$u){$s=$pdo->prepare('SELECT group_id FROM group_user WHERE user_id=:id');$s->execute(['id'=>$u['id']]);$u['groups']=array_map('intval',array_column($s->fetchAll(),'group_id'));$u['effective']=PermissionService::effective((int)$u['id']);$s=$pdo->prepare('SELECT permission_code,allowed FROM user_permission_overrides WHERE user_id=:id');$s->execute(['id'=>$u['id']]);$u['overrides']=[];foreach($s->fetchAll() as $r)$u['overrides'][$r['permission_code']]=(int)$r['allowed'];}View::render('admin/users',compact('users','groups','permissions'));}
 public function storeUser():void{$this->guard('admin.users.create');Security::verifyCsrf();$username=trim((string)($_POST['username']??''));$name=trim((string)($_POST['name']??''));$password=(string)($_POST['password']??'');if($username===''||$name===''||strlen($password)<8)exit('اطلاعات کاربر نامعتبر است.');$pdo=Database::connection();$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO users(username,name,password,is_active,created_at,updated_at) OUTPUT INSERTED.id VALUES(:username,:name,:password,1,GETDATE(),GETDATE())');$s->execute(['username'=>$username,'name'=>$name,'password'=>password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$s->fetchColumn();foreach((array)($_POST['groups']??[]) as $gid){$s=$pdo->prepare('INSERT INTO group_user(group_id,user_id) VALUES(:gid,:uid)');$s->execute(['gid'=>(int)$gid,'uid'=>$uid]);}$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}Security::redirect('/admin/users');}
 public function userStatus(int $id):void{$this->guard('admin.users.view');Security::verifyCsrf();$pdo=Database::connection();$s=$pdo->prepare('UPDATE users SET is_active=CASE WHEN is_active=1 THEN 0 ELSE 1 END,updated_at=GETDATE() WHERE id=:id');$s->execute(['id'=>$id]);Security::redirect('/admin/users');}
 public function userGroups(int $id):void{$this->guard('admin.users.permissions');Security::verifyCsrf();$pdo=Database::connection();$pdo->beginTransaction();try{$s=$pdo->prepare('DELETE FROM group_user WHERE user_id=:id');$s->execute(['id'=>$id]);$s=$pdo->prepare('INSERT INTO group_user(group_id,user_id) VALUES(:gid,:uid)');foreach((array)($_POST['groups']??[]) as $gid)$s->execute(['gid'=>(int)$gid,'uid'=>$id]);$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}Security::redirect('/admin/users');}
 public function userPermissions(int $id):void{$this->guard('admin.users.permissions');Security::verifyCsrf();$pdo=Database::connection();$pdo->beginTransaction();try{$s=$pdo->prepare('DELETE FROM user_permission_overrides WHERE user_id=:id');$s->execute(['id'=>$id]);$s=$pdo->prepare('INSERT INTO user_permission_overrides(user_id,permission_code,allowed,created_at,updated_at) VALUES(:uid,:code,:allowed,GETDATE(),GETDATE())');foreach((array)($_POST['permissions']??[]) as $code=>$allowed){if($allowed!=='')$s->execute(['uid'=>$id,'code'=>(string)$code,'allowed'=>(int)$allowed]);}$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}Security::redirect('/admin/users');}
}